/**
 * @file MovementType model
 * @author Lukas Courtney <lccourtney@ksu.edu>
 * @exports MovementTypeSchema the schema for the MovementType model
 */

// Import libraries
import Sequelize from "sequelize";

/**
 * @swagger
 * components:
 *   schemas:
 *     MovementType:
 *       type: object
 *       required:
 *         - type
 *       properties:
 *         id:
 *           type: integer
 *           description: autogenerated id
 *         type:
 *           type: string
 *           description: movement type name
 *         createdAt:
 *           type: string
 *           format: date-time
 *           description: when the movement type was created
 *         updatedAt:
 *           type: string
 *           format: date-time
 *           description: when the movement type was last updated
 *       example:
 *         id: 1
 *         type: damaged
 *         createdAt: 2025-02-04T15:36:32.000Z
 *         updatedAt: 2025-02-04T15:36:32.000Z
 */
const MovementTypeSchema = {
  id: {
    type: Sequelize.INTEGER,
    primaryKey: true,
    autoIncrement: true,
  },
  type: {
    type: Sequelize.STRING,
    allowNull: false,
    uniqueKey: true,
  },
  createdAt: {
    type: Sequelize.DATE,
    allowNull: false,
  },
  updatedAt: {
    type: Sequelize.DATE,
    allowNull: false,
  },
};

export default MovementTypeSchema;
